import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Banknote, CreditCard, Download, RefreshCcw, Search, TrendingUp, Wallet } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { Badge, Donut, EmptyState, Modal, PageHeader, StatCard } from '../lib/ui';
import { formatUZS, type Payment } from '../lib/mock';

export const Payments = () => {
  const { t } = useTranslation();
  const { payments, updatePaymentStatus, notify } = useAdmin();
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState('all');
  const [toRefund, setToRefund] = useState<Payment | null>(null);

  const filtered = useMemo(() => {
    let list = [...payments];
    const q = query.trim().toLowerCase();
    if (q) list = list.filter((p) => `${p.id} ${p.orderId} ${p.customer}`.toLowerCase().includes(q));
    if (status !== 'all') list = list.filter((p) => p.status === status);
    return list;
  }, [payments, query, status]);

  const revenue = payments.filter((p) => p.status === 'paid').reduce((s, p) => s + p.amount, 0);
  const pending = payments.filter((p) => p.status === 'pending').reduce((s, p) => s + p.amount, 0);
  const refunded = payments.filter((p) => p.status === 'refunded').reduce((s, p) => s + p.amount, 0);
  const card = payments.filter((p) => p.method === 'card').reduce((s, p) => s + p.amount, 0);
  const cash = payments.filter((p) => p.method === 'cash').reduce((s, p) => s + p.amount, 0);

  const refund = () => {
    if (!toRefund) return;
    updatePaymentStatus(toRefund.id, 'refunded');
    notify(`${toRefund.id} qaytarildi`);
    setToRefund(null);
  };

  const exportCsv = () => {
    const rows = [
      ['Transaction', 'Order', 'Customer', 'Amount', 'Method', 'Status', 'Date'],
      ...filtered.map((p) => [p.id, p.orderId, p.customer, String(p.amount), p.method, p.status, p.date]),
    ];
    const csv = rows.map((r) => r.map((v) => `"${v}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'maxshop-payments.csv';
    a.click();
    URL.revokeObjectURL(url);
    notify('CSV yuklab olindi', 'info');
  };

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('paymentsTitle')}
        subtitle={t('paymentsSubtitle')}
        action={<button className="btn-secondary btn-sm" onClick={exportCsv}><Download size={15} /> {t('export')}</button>}
      />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label={t('totalRevenue')} value={formatUZS(revenue)} icon={<Wallet size={20} />} />
        <StatCard label={t('pending')} value={formatUZS(pending)} icon={<RefreshCcw size={20} />} tone="amber" />
        <StatCard label={t('refunded')} value={formatUZS(refunded)} icon={<TrendingUp size={20} />} tone="violet" />
        <StatCard label="Tranzaksiyalar" value={String(payments.length)} icon={<CreditCard size={20} />} tone="sky" />
      </div>

      <div className="grid grid-cols-1 gap-5 xl:grid-cols-4">
        <div className="card p-5 xl:col-span-3">
          <div className="mb-4 flex flex-col gap-2 sm:flex-row">
            <div className="relative flex-1">
              <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
              <input className="input pl-10" placeholder="Tranzaksiya, buyurtma yoki mijoz..." value={query} onChange={(e) => setQuery(e.target.value)} />
            </div>
            <select className="select sm:w-44" value={status} onChange={(e) => setStatus(e.target.value)}>
              <option value="all">{t('all')}</option>
              <option value="paid">{t('paid')}</option>
              <option value="pending">{t('pending')}</option>
              <option value="refunded">{t('refunded')}</option>
            </select>
          </div>

          {filtered.length === 0 ? (
            <EmptyState title={t('noData')} />
          ) : (
            <div className="table-wrap">
              <table className="data-table min-w-[780px]">
                <thead>
                  <tr>
                    <th>{t('transaction')}</th>
                    <th>{t('order')}</th>
                    <th>{t('customer')}</th>
                    <th>{t('amount')}</th>
                    <th>{t('method')}</th>
                    <th>{t('status')}</th>
                    <th>{t('date')}</th>
                    <th className="text-right">{t('actions')}</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((p) => (
                    <tr key={p.id}>
                      <td className="text-xs font-extrabold">{p.id}</td>
                      <td className="text-xs font-bold">#{p.orderId}</td>
                      <td className="text-xs">{p.customer}</td>
                      <td className="text-xs font-extrabold">{formatUZS(p.amount)}</td>
                      <td>
                        <Badge tone={p.method === 'card' ? 'info' : 'neutral'}>
                          {p.method === 'card' ? <CreditCard size={11} /> : <Banknote size={11} />}
                          {p.method === 'card' ? t('card') : t('cash')}
                        </Badge>
                      </td>
                      <td><Badge tone={p.status === 'paid' ? 'success' : p.status === 'pending' ? 'warning' : 'danger'}>{t(p.status)}</Badge></td>
                      <td className="text-[10px] text-[var(--muted)]">{p.date}</td>
                      <td>
                        <div className="flex justify-end">
                          <button className="btn-secondary btn-sm" disabled={p.status !== 'paid'} onClick={() => setToRefund(p)}>
                            <RefreshCcw size={12} /> {t('refunded')}
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="space-y-4">
          <div className="card p-5">
            <h3 className="font-display text-base font-extrabold">To'lov usullari</h3>
            <p className="mt-0.5 text-xs text-[var(--muted)]">Karta va naqd nisbati</p>
            <div className="mt-4">
              <Donut
                total={card + cash}
                centerLabel="tranzaksiya"
                centerValue={String(payments.length)}
                segments={[
                  { label: t('card'), value: card, color: '#10b981' },
                  { label: t('cash'), value: cash, color: '#f59e0b' },
                ]}
              />
            </div>
          </div>
          <div className="card p-5">
            <h3 className="font-display text-base font-extrabold">Moliyaviy holat</h3>
            <div className="mt-3 space-y-3">
              <div className="flex items-center justify-between text-xs"><span className="text-[var(--muted)]">Karta orqali</span><b>{formatUZS(card)}</b></div>
              <div className="flex items-center justify-between text-xs"><span className="text-[var(--muted)]">Naqd pul</span><b>{formatUZS(cash)}</b></div>
              <div className="flex items-center justify-between text-xs"><span className="text-[var(--muted)]">Kutilayotgan</span><b className="text-amber-500">{formatUZS(pending)}</b></div>
              <div className="flex items-center justify-between border-t pt-2 text-xs" style={{ borderColor: 'var(--border)' }}><span className="text-[var(--muted)]">Sof tushum</span><b className="text-brand-600 dark:text-brand-400">{formatUZS(revenue - refunded)}</b></div>
            </div>
          </div>
        </div>
      </div>

      <Modal open={!!toRefund} onClose={() => setToRefund(null)} title={t('refunded')} subtitle="Tranzaksiyani qaytarishni tasdiqlang">
        <div className="rounded-2xl bg-amber-500/10 p-3 text-center">
          <p className="font-display text-lg font-extrabold">{toRefund?.id}</p>
          <p className="text-xs text-[var(--muted)]">{toRefund?.customer} · {toRefund ? formatUZS(toRefund.amount) : ''}</p>
        </div>
        <div className="mt-5 flex gap-2">
          <button className="btn-secondary flex-1" onClick={() => setToRefund(null)}>{t('cancel')}</button>
          <button className="btn flex-1 bg-rose-500 text-white hover:bg-rose-600" onClick={refund}>{t('refunded')}</button>
        </div>
      </Modal>
    </div>
  );
};
